import { html, createSignal, createEffect, useKeyboard } from 'onefold';
import { PlayIcon, ExpandIcon, ShrinkIcon } from './SvgIcon';

/**
 * Strips TypeScript type annotations so code can execute as plain JS in the browser.
 */
function stripTypes(code: string): string {
  return code
    .replace(/^(export\s+)?(interface|type)\s+\w+[^]*?\n\}/gm, '')
    .replace(/\)\s*:\s*[A-Za-z<>\[\]|&\s,]+\s*\{/g, ') {')
    .replace(/\)\s*:\s*[A-Za-z<>\[\]|&\s,]+\s*=>/g, ') =>')
    .replace(/(const|let|var)\s+(\w+)\s*:\s*[A-Za-z<>\[\]|&\s,]+\s*=/g, '$1 $2 =')
    .replace(/(\w)\s*:\s*(?:[A-Z]\w*(?:<[^>]*>)?(?:\[\])?|string|number|boolean|void|any|unknown|never)(\s*[,)=])/g, '$1$2')
    .replace(/(\w)<[^>]+>\(/g, '$1(')
    .replace(/\s+as\s+[A-Z]\w*(?:<[^>]*>)?/g, '')
    .replace(/\n{3,}/g, '\n\n');
}

/**
 * Playground component inspired by the TypeScript Playground.
 * 
 * Features:
 * - Line numbers gutter
 * - Tabbed output: Result (rendered DOM) / Console (captured logs)
 * - Resizable panels via drag divider
 * - Auto-run with 800ms debounce on code changes
 * - Tab key inserts spaces
 * - Reset to initial code
 */
export function Playground(initialCode: string, title = 'Live Example'): Node {
  const code = createSignal(initialCode.trim());
  const iframeRef = createSignal<HTMLIFrameElement | null>(null);
  const activeTab = createSignal<'result' | 'console'>('result');
  const logs = createSignal<string[]>([]);
  const lineCount = createSignal(initialCode.trim().split('\n').length);
  const running = createSignal(false);
  const isFullscreen = createSignal(false);

  const toggleFullscreen = () => {
    isFullscreen.set(v => !v);
    document.body.style.overflow = isFullscreen() ? 'hidden' : '';
  };

  // Keyboard shortcuts: Esc to exit fullscreen, Ctrl+Enter to run
  useKeyboard({
    'Escape': () => {
      if (isFullscreen()) {
        isFullscreen.set(false);
        document.body.style.overflow = '';
      }
    },
    'Ctrl+Enter': () => run(),
  });

  // --- Build the iframe srcdoc ---
  const buildSrcdoc = (source: string): string => {
    const jsCode = stripTypes(source);
    const escapedCode = JSON.stringify(jsCode);

    return [
      '<!DOCTYPE html><html><head><meta charset="utf-8">',
      '<style>',
      '* { box-sizing: border-box; margin: 0; font-family: -apple-system, BlinkMacSystemFont, sans-serif; }',
      'body { padding: 12px; font-size: 14px; line-height: 1.6; color: #1a1a2e; }',
      'button { padding: 6px 12px; border-radius: 4px; border: 1px solid #e5e7eb; cursor: pointer; margin: 4px 4px 4px 0; background: #fff; }',
      'button:hover { background: #f3f4f6; }',
      'h1,h2,h3 { margin-bottom: 8px; }',
      'p { margin-bottom: 8px; }',
      'input,textarea,select { padding: 6px 10px; border: 1px solid #e5e7eb; border-radius: 4px; margin: 4px 0; font-size: 14px; }',
      'ul,ol { padding-left: 20px; }',
      'li { margin: 4px 0; }',
      '.error { color: #dc2626; font-family: monospace; font-size: 12px; white-space: pre-wrap; padding: 8px; background: #fef2f2; border-radius: 4px; }',
      '</style></head><body>',
      '<div id="app"></div>',
      '<script type="module">',
      'const CODE = ' + escapedCode + ';',
      '',
      '// Console capture',
      'const _logs = [];',
      'const _origLog = console.log;',
      'console.log = (...a) => { _logs.push(a.map(x => typeof x === "object" ? JSON.stringify(x,null,2) : String(x)).join(" ")); _origLog(...a); window.parent.postMessage({type:"pg-log",logs:[..._logs]},"*"); };',
      'console.warn = (...a) => console.log("[warn]", ...a);',
      'console.error = (...a) => console.log("[error]", ...a);',
      '',
      '// Minimal reactive runtime',
      'let _ae = null;',
      'function createSignal(init) {',
      '  let val = init; const subs = new Set();',
      '  const sig = () => { if (_ae) subs.add(_ae); return val; };',
      '  sig.set = (v) => { const nv = typeof v === "function" ? v(val) : v; if (Object.is(nv, val)) return; val = nv; for (const s of [...subs]) s(); };',
      '  sig.peek = () => val; return sig;',
      '}',
      'function createEffect(fn) { const eff = () => { const p = _ae; _ae = eff; try { fn(); } finally { _ae = p; } }; eff(); return () => {}; }',
      'function createComputed(fn) { const s = createSignal(undefined); createEffect(() => s.set(fn())); const r = () => s(); r.peek = s.peek; r.set = () => { throw new Error("Cannot write to computed"); }; return r; }',
      'function batch(fn) { fn(); }',
      '',
      'function html(strings, ...values) {',
      '  const PH = "\\x01PH";',
      '  let markup = "";',
      '  for (let i = 0; i < strings.length; i++) { markup += strings[i]; if (i < values.length) { const v = values[i]; if (typeof v === "string" || typeof v === "number") markup += String(v); else markup += PH + i + "\\x01"; } }',
      '  const tpl = document.createElement("template"); tpl.innerHTML = markup; const frag = tpl.content;',
      '',
      '  const walker = document.createTreeWalker(frag, NodeFilter.SHOW_TEXT);',
      '  const tns = []; while (walker.nextNode()) tns.push(walker.currentNode);',
      '  for (const tn of tns) {',
      '    const re = /\\x01PH(\\d+)\\x01/g; let m;',
      '    if ((m = re.exec(tn.textContent)) !== null) {',
      '      const idx = parseInt(m[1]); const val = values[idx];',
      '      if (typeof val === "function") {',
      '        const marker = document.createTextNode(""); tn.replaceWith(marker); let cur = [];',
      '        createEffect(() => {',
      '          const r = val(); for (const n of cur) n.remove(); cur = [];',
      '          if (Array.isArray(r)) { const p = marker.parentNode; if (p) for (const c of r) { if (c instanceof Node) { p.insertBefore(c, marker); cur.push(c); } else { const t = document.createTextNode(String(c??"")); p.insertBefore(t, marker); cur.push(t); } } }',
      '          else if (r instanceof Node) { if (marker.parentNode) { marker.parentNode.insertBefore(r, marker); cur.push(r); } }',
      '          else { const t = document.createTextNode(String(r??"")); if (marker.parentNode) { marker.parentNode.insertBefore(t, marker); cur.push(t); } }',
      '        });',
      '      } else if (val instanceof Node) { tn.replaceWith(val); }',
      '    }',
      '  }',
      '',
      '  frag.querySelectorAll("*").forEach(el => {',
      '    for (const attr of [...el.attributes]) {',
      '      const m2 = attr.value.match(/\\x01PH(\\d+)\\x01/);',
      '      if (m2) {',
      '        const idx = parseInt(m2[1]); const val = values[idx];',
      '        if (attr.name.startsWith("on") && typeof val === "function") { el.removeAttribute(attr.name); el.addEventListener(attr.name.slice(2), val); }',
      '        else if (attr.name === "class" && typeof val === "function") { el.removeAttribute(attr.name); createEffect(() => { el.className = val() || ""; }); }',
      '        else if (attr.name === "style" && typeof val === "object") { el.removeAttribute(attr.name); Object.assign(el.style, val); }',
      '        else if (typeof val === "function") { el.removeAttribute(attr.name); createEffect(() => { const v = val(); if (v === false || v == null) el.removeAttribute(attr.name); else el.setAttribute(attr.name, String(v)); }); }',
      '        else { el.setAttribute(attr.name, String(val ?? "")); }',
      '      }',
      '    }',
      '  });',
      '',
      '  if (frag.childNodes.length === 1 && frag.firstChild instanceof HTMLElement) return frag.firstChild;',
      '  const w = document.createElement("div"); w.appendChild(frag); return w;',
      '}',
      '',
      'function mount(node, container) { container.replaceChildren(node); }',
      'function css() { return { scope: "", css: "" }; }',
      '',
      'try {',
      '  const fn = new Function("createSignal","createEffect","createComputed","batch","html","mount","css",',
      '    CODE + "\\n\\n" +',
      '    "if (typeof App===\\"function\\") mount(App(), document.getElementById(\\"app\\"));\\n" +',
      '    "else if (typeof Counter===\\"function\\") mount(Counter(), document.getElementById(\\"app\\"));\\n" +',
      '    "else if (typeof Main===\\"function\\") mount(Main(), document.getElementById(\\"app\\"));\\n" +',
      '    "else if (typeof Todo===\\"function\\") mount(Todo(), document.getElementById(\\"app\\"));\\n"',
      '  );',
      '  fn(createSignal, createEffect, createComputed, batch, html, mount, css);',
      '  window.parent.postMessage({type:"pg-ready"},"*");',
      '} catch(e) {',
      '  document.getElementById("app").innerHTML = \'<div class="error">\' + e.message + \'</div>\';',
      '  window.parent.postMessage({type:"pg-log",logs:["[error] " + e.message]},"*");',
      '}',
      '<\/script></body></html>',
    ].join('\n');
  };

  // --- Run ---
  const run = () => {
    const iframe = iframeRef();
    if (!iframe) return;
    running.set(true);
    logs.set([]);
    iframe.srcdoc = buildSrcdoc(code());
    setTimeout(() => running.set(false), 300);
  };

  // --- Debounced auto-run ---
  let autoRunTimer: ReturnType<typeof setTimeout> | null = null;
  const scheduleAutoRun = () => {
    if (autoRunTimer) clearTimeout(autoRunTimer);
    autoRunTimer = setTimeout(run, 800);
  };

  // --- Event handlers ---
  const handleInput = (e: Event) => {
    const val = (e.target as HTMLTextAreaElement).value;
    code.set(val);
    lineCount.set(val.split('\n').length);
    scheduleAutoRun();
  };

  const handleKeyDown = (e: KeyboardEvent) => {
    if (e.key === 'Tab') {
      e.preventDefault();
      const ta = e.target as HTMLTextAreaElement;
      const start = ta.selectionStart;
      const end = ta.selectionEnd;
      ta.value = ta.value.substring(0, start) + '  ' + ta.value.substring(end);
      ta.selectionStart = ta.selectionEnd = start + 2;
      code.set(ta.value);
      lineCount.set(ta.value.split('\n').length);
      scheduleAutoRun();
    }
  };

  const handleEditorScroll = (e: Event) => {
    const ta = e.target as HTMLTextAreaElement;
    const gutter = ta.previousElementSibling as HTMLElement;
    if (gutter) gutter.scrollTop = ta.scrollTop;
  };

  const resetCode = () => {
    code.set(initialCode.trim());
    lineCount.set(initialCode.trim().split('\n').length);
    // Update textarea value directly
    const ta = document.querySelector('.playground-editor') as HTMLTextAreaElement | null;
    if (ta) ta.value = initialCode.trim();
    run();
  };

  // --- Listen for postMessage from iframe ---
  if (typeof window !== 'undefined') {
    window.addEventListener('message', (e) => {
      if (e.data?.type === 'pg-log') {
        logs.set(e.data.logs ?? []);
      }
    });
  }

  // --- Resize divider ---
  const initDragResize = (divider: HTMLElement) => {
    let dragging = false;
    let startX = 0;
    let startWidth = 0;

    divider.addEventListener('mousedown', (e: MouseEvent) => {
      dragging = true;
      startX = e.clientX;
      startWidth = (divider.previousElementSibling as HTMLElement).getBoundingClientRect().width;
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
      e.preventDefault();
    });

    document.addEventListener('mousemove', (e: MouseEvent) => {
      if (!dragging) return;
      const container = divider.parentElement as HTMLElement;
      const maxW = container.getBoundingClientRect().width - 120;
      const newW = Math.max(120, Math.min(maxW, startWidth + (e.clientX - startX)));
      const pct = (newW / container.getBoundingClientRect().width) * 100;
      (divider.previousElementSibling as HTMLElement).style.cssText = `flex:none;width:${pct}%;min-width:120px`;
      (divider.nextElementSibling as HTMLElement).style.flex = '1';
    });

    document.addEventListener('mouseup', () => {
      if (!dragging) return;
      dragging = false;
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    });
  };

  // --- Auto-run on first mount ---
  setTimeout(run, 200);

  // --- Render ---
  return html`
    <div class=${() => 'playground' + (isFullscreen() ? ' playground-fullscreen' : '')}>
      <div class="playground-toolbar">
        <div class="playground-toolbar-left">
          <span class="playground-title">${title}</span>
        </div>
        <div class="playground-toolbar-right">
          <button class="pg-btn pg-btn-run" onclick=${run}>
            ${PlayIcon()}
            Run
          </button>
          <button class="pg-btn" onclick=${resetCode}>Reset</button>
          <button class="pg-btn" onclick=${toggleFullscreen} title="Toggle fullscreen (Esc to exit)">
            ${() => isFullscreen() ? ShrinkIcon() : ExpandIcon()}
          </button>
        </div>
      </div>
      <div class="playground-body">
        <div class="playground-left">
          <div class="pg-gutter">${() =>
            Array.from({ length: lineCount() }, (_, i) =>
              html`<div class="pg-line-num">${String(i + 1)}</div>`
            )
          }</div>
          <textarea
            class="playground-editor"
            oninput=${handleInput}
            onkeydown=${handleKeyDown}
            onscroll=${handleEditorScroll}
            spellcheck="false"
            autocomplete="off"
            autocorrect="off"
            autocapitalize="off"
          >${initialCode.trim()}</textarea>
        </div>
        <div class="playground-divider" ref=${(el: HTMLElement) => initDragResize(el)}></div>
        <div class="playground-right">
          <div class="pg-tabs">
            <button class=${() => 'pg-tab' + (activeTab() === 'result' ? ' active' : '')} onclick=${() => activeTab.set('result')}>Result</button>
            <button class=${() => 'pg-tab' + (activeTab() === 'console' ? ' active' : '')} onclick=${() => activeTab.set('console')}>
              Console${() => logs().length > 0 ? html`<span class="pg-tab-badge">${String(logs().length)}</span>` : ''}
            </button>
          </div>
          <div class="pg-output-result" style=${() => activeTab() === 'result' ? '' : 'display:none'}>
            <iframe
              ref=${(el: HTMLIFrameElement) => iframeRef.set(el)}
              sandbox="allow-scripts"
            ></iframe>
          </div>
          <div class="pg-output-console" style=${() => activeTab() === 'console' ? '' : 'display:none'}>
            ${() => logs().length === 0
              ? html`<div class="pg-console-empty">No output. Run the code to see console.log results.</div>`
              : html`<div class="pg-console-entries">${logs().map(l => html`<div class="pg-console-line"><span class="pg-console-chevron">${'>'}</span> ${l}</div>`)}</div>`
            }
          </div>
        </div>
      </div>
    </div>
  `;
}
